function db(){return new Promise((r,j)=>{let q=indexedDB.open('at_ai_m8_downloads_v1',1);q.onupgradeneeded=()=>q.result.createObjectStore('d',{keyPath:'key'});q.onsuccess=()=>r(q.result);q.onerror=()=>j(q.error)})}
async function get(k){let d=await db();return new Promise(r=>{let q=d.transaction('d').objectStore('d').get(k);q.onsuccess=q.onerror=()=>{r(q.result);d.close()}})}
async function getAll(){let d=await db();return new Promise(r=>{let q=d.transaction('d').objectStore('d').getAll();q.onsuccess=()=>{r(q.result||[]);d.close()};q.onerror=()=>{r([]);d.close()}})}
