async function catalog(a,b){
  const m=new Map(),seen=new Set(),days=[];
  for(let d=new Date(a+'T12:00:00');d<=new Date(b+'T12:00:00');d.setDate(d.getDate()+1))days.push(d.toISOString().slice(0,10));
  let done=0,raw=0;
  const take=async day=>{
    if(stop)return;
    const x=await fetch('/api/tjk-race-query-v1?start='+day+'&end='+day+'&page=0',{cache:'no-store'}),j=await x.json();
    if(!j.ok)throw Error(j.error||day+' sorgu hatası');
    const rr=Array.isArray(j.rows)?j.rows:[];
    if(Number(j.total||0)>rr.length)throw Error(day+' günlük sorgu eksik: '+rr.length+' / '+j.total);
    raw+=rr.length;
    for(const z of rr){
      const rk=z.canonicalRaceId||z.key||[z.date,z.city,z.winner,z.winnerDegree,z.raceType,z.group,z.distance,z.origin].join('|');
      if(seen.has(rk))continue;seen.add(rk);
      const k=z.date+'|'+z.city,v=m.get(k)||{key:k,date:z.date,city:z.city,count:0};
      v.count++;m.set(k,v)
    }
    done++;m8sum.textContent='Koşu Sorgulama gün gün alınıyor · '+done+'/'+days.length+' gün · '+seen.size+' yarış';
  };
  for(let i=0;i<days.length&&!stop;i+=8)await Promise.all(days.slice(i,i+8).map(take));
  if(stop)return;
  rows=[...m.values()].sort((a,b)=>b.date.localeCompare(a.date)||a.city.localeCompare(b.city,'tr'));
  window.__M8_QUERY_TOTAL__={unique:seen.size,raw,days:done,method:'DAILY_EXHAUSTIVE'}
}
async function chooseDir(){if(!window.showDirectoryPicker)throw Error('Bu tarayıcı kalıcı klasör erişimini desteklemiyor');let picked=await window.showDirectoryPicker({mode:'readwrite'}),p=await picked.requestPermission({mode:'readwrite'});if(p!=='granted')throw Error('Klasör yazma izni verilmedi');if(picked.name==='Gerçek Yarış Arşivi'){rootDir=picked;rootDirIsRace=true;m8folder.textContent='✓ Klasör: Gerçek Yarış Arşivi'}else{rootDir=picked;rootDirIsRace=false;m8folder.textContent='✓ Klasör: '+rootDir.name}return rootDir}
async function openAnyDb(name){return new Promise(r=>{let q=indexedDB.open(name);q.onsuccess=()=>r(q.result);q.onerror=q.onblocked=()=>r(null)})}
async function realArchiveYear(year){let db=await openAnyDb('at_ai_tjk_annual_results_v1');if(!db||!db.objectStoreNames.contains('races'))return[];return new Promise(r=>{let out=[],os=db.transaction('races','readonly').objectStore('races'),idx=os.indexNames.contains('year')?os.index('year'):null;if(!idx){db.close();return r([])}let q=idx.openCursor(IDBKeyRange.only(Number(year)));q.onsuccess=()=>{let cur=q.result;if(!cur){db.close();return r(out)}out.push(cur.value);cur.continue()};q.onerror=()=>{db.close();r(out)}})}
async function deleteRealArchiveGroup(group){let db=await openAnyDb('at_ai_tjk_annual_results_v1');if(!db||!db.objectStoreNames.contains('races'))return 0;return new Promise(r=>{let n=0,tx=db.transaction('races','readwrite'),os=tx.objectStore('races');for(const x of group.races||[]){if(x?.key){os.delete(x.key);n++}}tx.oncomplete=()=>{db.close();r(n)};tx.onerror=tx.onabort=()=>{try{db.close()}catch{}r(0)}})}
async function migrateRealArchive(){if(!rootDir)throw Error('Önce AT AI MOBIL klasörünü seçin');let y=Number(m8y.value);if(!y)throw Error('Aktarılacak yılı seçin');let races=await realArchiveYear(y);if(!races.length)throw Error(y+' için Gerçek Yarış Arşivinde kayıt bulunamadı');let groups=new Map();for(const x of races){if(!x.date||!x.city)continue;let k=x.date+'|'+x.city,g=groups.get(k)||{key:k,date:x.date,city:x.city,count:0,races:[]};g.count++;g.races.push(x);groups.set(k,g)}let arr=[...groups.values()],ok=0,skipped=0,deleted=0,err=0;m8sum.textContent=y+' gerçek arşivi · '+arr.length+' gün/şehir kontrol edilecek';for(const g of arr){if(stop)break;try{let existing=await readArchive(g.date,g.city);if(existing){skipped++;let n=await deleteRealArchiveGroup(g);if(n===g.races.length)deleted+=n;else if(n)throw Error('IndexedDB temizleme eksik')}else{await saveFile(g,{ok:true,source:'at_ai_tjk_annual_results_v1',races:g.races});let verify=await readArchive(g.date,g.city);if(!verify||!Array.isArray(verify?.data?.races)||verify.data.races.length!==g.races.length)throw Error('Kalıcı dosya doğrulanamadı');ok++;let n=await deleteRealArchiveGroup(g);if(n===g.races.length)deleted+=n;else if(n)throw Error('IndexedDB temizleme eksik')}}catch(e){err++}m8sum.textContent=y+' aktarım · '+(ok+skipped+err)+'/'+arr.length+' · Yeni '+ok+' · Zaten Var '+skipped+' · IndexedDB’den Silinen '+deleted+' yarış · Hata '+err;await new Promise(q=>setTimeout(q,10))}m8sum.textContent=y+' gerçek arşivi · Yeni '+ok+' · Zaten Var '+skipped+' · IndexedDB’den Silinen '+deleted+' yarış · '+err+' hata';return{ok,skipped,deleted,err}}
async function migrateOld(){if(!rootDir)throw Error('Önce AT AI MOBIL klasörünü seçin');let y=m8y.value,c=m8c.value,a=m8a.value,b=m8b.value,all=await getAll(),src=all.filter(x=>x&&x.data&&x.date&&x.city&&(!y||x.date.startsWith(y))&&(!c||x.city===c)&&(!a||x.date>=a)&&(!b||x.date<=b)),ok=0,err=0;m8sum.textContent='Eski arşiv taranıyor · '+src.length+' kayıt';for(const x of src){if(stop)break;try{let r={key:x.key,date:x.date,city:x.city,count:x.count||0};await saveFile(r,x.data);await del(x.key);ok++}catch(e){err++}m8sum.textContent='Aktarım · '+(ok+err)+'/'+src.length+' · Başarılı '+ok+' · Hata '+err;await new Promise(q=>setTimeout(q,20))}m8sum.textContent='Aktarım tamamlandı · '+ok+' taşındı ve IndexedDB’den silindi · '+err+' hata';return{ok,err}}
async function readArchive(date,city){if(!rootDir)return null;try{let race=rootDirIsRace?rootDir:await rootDir.getDirectoryHandle('Gerçek Yarış Arşivi'),yr=await race.getDirectoryHandle(String(date).slice(0,4)),name=date+'_'+String(city).replace(/[^a-zA-Z0-9ğüşöçıİĞÜŞÖÇ_-]+/g,'_')+'.json',fh=await yr.getFileHandle(name),file=await fh.getFile();return JSON.parse(await file.text())}catch(e){return null}}
async function horseHistoryFile(atId){if(!rootDir)return null;try{let d=await rootDir.getDirectoryHandle('At Yarış İndeksi'),fh=await d.getFileHandle(String(atId)+'.json'),f=await fh.getFile();return JSON.parse(await f.text())}catch(e){return null}}
async function saveHorseHistory(atId,data){if(!rootDir)return false;let p=await rootDir.queryPermission({mode:'readwrite'});if(p!=='granted')p=await rootDir.requestPermission({mode:'readwrite'});if(p!=='granted')return false;let d=await rootDir.getDirectoryHandle('At Yarış İndeksi',{create:true}),fh=await d.getFileHandle(String(atId)+'.json',{create:true}),w=await fh.createWritable();await w.write(JSON.stringify({version:'AT-HISTORY-LOCAL-V1',savedAt:new Date().toISOString(),atId:String(atId),data},null,2));await w.close();return true}
async function getHorseHistory(atId,opt={}){atId=String(atId||'').replace(/\D/g,'');if(!atId)throw Error('AtId gerekli');let local=await horseHistoryFile(atId);if(local&&!opt.refresh)return{source:'phone',record:local};let r=await fetch('/api/tjk-horse-history-v1?atId='+encodeURIComponent(atId),{cache:'no-store'}),j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'At geçmişi alınamadı');if(rootDir)await saveHorseHistory(atId,j);return{source:'tjk',record:j}}
async function resolveHorseRaces(atId,opt={}){let h=await getHorseHistory(atId,opt),src=h?.record?.data||h?.record||{},list=src.races||[],out=[];for(const r of list){if(!r.date||!r.city)continue;let a=await readArchive(r.date,r.city);if(a){out.push({history:r,archiveSource:'phone',archive:a});continue}let legacy=await get(r.date+'|'+r.city);if(legacy)out.push({history:r,archiveSource:'indexeddb',archive:legacy});else out.push({history:r,archiveSource:'missing',archive:null})}return{atId:String(atId),historySource:h.source,total:list.length,matched:out.filter(x=>x.archive).length,missing:out.filter(x=>!x.archive).length,races:out}}
function fogdYear(data){let v=data?.raceDate||data?.data?.raceDate||data?.savedAt||'';let m=String(v).match(/(20\\d{2})/);return m?m[1]:String(new Date().getFullYear())}
