window.AT_AI_LOCAL_ARCHIVE={version:'F60.94.32.18',ready:()=>!!rootDir,select:chooseDir,read:readArchive,legacyGet:get,horseHistory:getHorseHistory,saveHorseHistory,resolveHorseRaces,getFogd,saveFogd,async get(date,city){let x=await readArchive(date,city);if(x)return{source:'phone',record:x};let y=await get(date+'|'+city);return y?{source:'indexeddb',record:y}:null}};
